100: import { normaliseRegion, regionScope, chosenOrder, send } from './helpers.js';
101: 
102: export async function paymentFeed(db, input) {
103:   const order = chosenOrder(input.order);
104:   const rows = await db.query('SELECT id,total_cents,created_at FROM invoices ORDER BY ' + order + ' LIMIT :limit', {limit:25});
105:   return rows.map(row => ({...row, dollars:row.total_cents / 100}));
106: }
107: export async function revenueSummary(db, request) {
108:   const region = normaliseRegion(request.region);
109:   const scope = regionScope(region);
110:   const rows = await db.query('SELECT region,COUNT(*) count,SUM(total_cents) cents FROM invoices WHERE created_at>=:from AND created_at<:to AND ' + scope + ' GROUP BY region', {from:request.from,to:request.to});
111:   return rows.map(row => ({...row, dollars:row.cents / 100}));
112: }
113: export async function removeVoid(db, invoiceId) {
114:   const result = await send(db, "DELETE FROM invoices WHERE id=:invoiceId AND status='void'", {invoiceId});
115:   return { removed: result.changes };
116: }

1: export function page(value, size = 50) {
2:   const current = Math.max(0, Number(value) || 0);
3:   return { limit: Math.min(size, 100), offset: current * size };
4: }
5: export function chosenOrder(value) {
6:   const choices = Object.freeze({
7:     recent: 'created_at DESC',
8:     amount: 'total_cents DESC',
9:     name: 'customer_id ASC'
10:   });
11:   return Object.hasOwn(choices, value) ? choices[value] : choices.recent;
12: }
13: export function normaliseRegion(value) {
14:   return String(value || '').trim();
15: }
16: export function regionScope(value) {
17:   return value ? "region = '" + value + "'" : '1 = 1';
18: }
19: export async function send(db, text, values = {}) {
20:   return db.query(text, values);
21: }

1: import * as store from './store.js';
2: 
3: export async function getInvoice(db, params) {
4:   const [invoice] = await store.findInvoice(db, params.invoiceId);
5:   return invoice ? {status:200,body:invoice} : {status:404,body:{error:'missing'}};
6: }
7: export async function postInvoice(db, body) {
8:   await store.insertInvoice(db, body);
9:   for (const line of body.lines || []) await store.insertInvoiceLine(db, body.id, line.sku, line.description, line.quantity, line.unitCents);
10:   await store.repriceInvoice(db, body.id);
11:   return {status:201,body:{id:body.id}};
12: }
13: export async function revenueReport(db, query) {
14:   return {status:200,body:await store.revenueSummary(db, query)};
15: }
16: export async function customerPage(db, query) {
17:   const p = query.page || 0;
18:   return {status:200,body:await store.searchCustomer(db, '%'+(query.q||'')+'%', 25, p*25)};
19: }

